-- Stage 4 local-only synthetic query-plan evidence. Always ROLLBACK; never deploy or seed.

-- Credential verifier is a deliberately unusable placeholder; no real credential or secret is created.

SET NAMES utf8mb4;

START TRANSACTION;







SELECT 'PLAN_scope_exact';

EXPLAIN FORMAT=JSON SELECT api_scope_id,scope_code,display_name,description,version,create_time,update_time FROM t_api_scope WHERE scope_code='explain0927f24e8b06.s000' AND BINARY scope_code=BINARY 'explain0927f24e8b06.s000';

SELECT 'PLAN_credential_reference_page';

EXPLAIN FORMAT=JSON SELECT c.credential_id credentialId,c.tenant_id tenantId,t.tenant_type tenantType,t.owner_ref_id clientId,
        t.tenant_name clientName,c.key_prefix keyPrefix,c.status storedStatus,t.owner_status tenantOwnerStatus,
        t.security_status tenantSecurityStatus,c.expires_time expiresTime,c.rotated_from_id rotatedFromId,
        c.version,c.create_time createTime,c.update_time updateTime FROM t_api_credential c LEFT JOIN t_access_tenant t ON t.tenant_id=c.tenant_id WHERE (t.tenant_type='CLIENT' OR t.tenant_id IS NULL) AND EXISTS(SELECT 1 FROM t_api_credential_scope g WHERE g.credential_id=c.credential_id AND g.scope_code='explain0927f24e8b06.s000' AND BINARY g.scope_code=BINARY 'explain0927f24e8b06.s000') ORDER BY c.credential_id LIMIT 20 OFFSET 0;

SELECT 'PLAN_credential_reference_count';

EXPLAIN FORMAT=JSON SELECT COUNT(*) FROM t_api_credential c LEFT JOIN t_access_tenant t ON t.tenant_id=c.tenant_id WHERE (t.tenant_type='CLIENT' OR t.tenant_id IS NULL) AND EXISTS(SELECT 1 FROM t_api_credential_scope g WHERE g.credential_id=c.credential_id AND g.scope_code='explain0927f24e8b06.s000' AND BINARY g.scope_code=BINARY 'explain0927f24e8b06.s000');

SELECT 'PLAN_route_reference_page';

EXPLAIN FORMAT=JSON SELECT r.route_id routeId, r.route_code routeCode, r.channel, r.http_method httpMethod,
        r.external_path_template externalPathTemplate, r.downstream_path_template downstreamPathTemplate,
        r.target_id targetId, t.target_service_code targetServiceCode, t.status targetStatus,
        r.security_profile_code securityProfileCode, r.authorization_mode authorizationMode,
        r.permission_id permissionId, p.permission_code permissionCode, r.required_scope_code requiredScopeCode,
        r.request_cookie_mode requestCookieMode, r.response_cookie_mode responseCookieMode,
        r.body_limit_bytes bodyLimitBytes, r.body_receive_timeout_millis bodyReceiveTimeoutMillis,
        r.response_timeout_millis responseTimeoutMillis, r.status, r.version, r.created_by createdBy,
        r.updated_by updatedBy, r.create_time createTime, r.update_time updateTime FROM t_gateway_route r
        JOIN t_gateway_target t ON t.target_id=r.target_id AND t.channel=r.channel
        LEFT JOIN t_permission p ON p.permission_id=r.permission_id WHERE r.required_scope_code='explain0927f24e8b06.s000' AND BINARY r.required_scope_code=BINARY 'explain0927f24e8b06.s000' ORDER BY r.route_code,r.route_id LIMIT 20 OFFSET 0;

SELECT 'PLAN_route_reference_count';

EXPLAIN FORMAT=JSON SELECT COUNT(*) FROM t_gateway_route r
        JOIN t_gateway_target t ON t.target_id=r.target_id AND t.channel=r.channel
        LEFT JOIN t_permission p ON p.permission_id=r.permission_id WHERE r.required_scope_code='explain0927f24e8b06.s000' AND BINARY r.required_scope_code=BINARY 'explain0927f24e8b06.s000';

SELECT 'FIXTURE_COUNTS';

SELECT JSON_OBJECT('scopes',(SELECT COUNT(*) FROM t_api_scope WHERE scope_code LIKE 'explain0927f24e8b06%'),'credentials',(SELECT COUNT(*) FROM t_api_credential WHERE tenant_id=810913170000000000),'grants',(SELECT COUNT(*) FROM t_api_credential_scope WHERE scope_code LIKE 'explain0927f24e8b06%'),'routes',(SELECT COUNT(*) FROM t_gateway_route WHERE route_code LIKE 'explain0927f24e8b06%'));

ROLLBACK;

SELECT 'AFTER_ROLLBACK';

SELECT JSON_OBJECT('scopes',(SELECT COUNT(*) FROM t_api_scope WHERE scope_code LIKE 'explain0927f24e8b06%'),'credentials',(SELECT COUNT(*) FROM t_api_credential WHERE tenant_id=810913170000000000),'grants',(SELECT COUNT(*) FROM t_api_credential_scope WHERE scope_code LIKE 'explain0927f24e8b06%'),'routes',(SELECT COUNT(*) FROM t_gateway_route WHERE route_code LIKE 'explain0927f24e8b06%'),'tenant',(SELECT COUNT(*) FROM t_access_tenant WHERE tenant_id=810913170000000000),'target',(SELECT COUNT(*) FROM t_gateway_target WHERE target_id=810913170000000000));
